import { ReactNode, FC } from 'react';

interface SwiperProps {
    /** 当前索引 (受控) */
    current?: number;
    /** 默认索引 (非受控) */
    defaultCurrent?: number;
    /** 是否自动播放 */
    autoplay?: boolean;
    /** 自动播放间隔 (ms) */
    interval?: number;
    /** 动画时长 (ms) */
    duration?: number;
    /** 是否循环 */
    loop?: boolean;
    /** 是否垂直方向 */
    vertical?: boolean;
    /** 是否显示指示器 */
    showIndicator?: boolean;
    /** 指示器颜色 */
    indicatorColor?: string;
    /** 激活指示器颜色 */
    indicatorActiveColor?: string;
    /** 切换回调 */
    onChange?: (current: number) => void;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface SwiperItemProps {
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const SwiperItem: FC<SwiperItemProps>;
type SwiperComponent = FC<SwiperProps> & {
    Item: FC<SwiperItemProps>;
};
declare const Swiper: SwiperComponent;

export { Swiper, SwiperItem, Swiper as default };
export type { SwiperItemProps, SwiperProps };
